'use strict';

// Deals a random starting table, recreating the Main sheet of SituationSimulator.xlsx.
// Data comes from data.js (generated by tools/export_data.py).

// Card sets. Approaches, resources and the Fate deck are shared by every theme; data.js
// (GAME_DATA, from the spreadsheet) still supplies those and the card icons, but its own Film
// Noir cards are no longer a set you can pick (removed 2026-10-21).
const THEMES = {
  bladerunner: { label: 'Blade Runner', data: window.BLADE_RUNNER_DATA },
  ghostbusters: { label: 'Ghostbusters', data: window.GHOSTBUSTERS_DATA },
  starwars: { label: 'Star Wars', data: window.STAR_WARS_DATA },
  lotr: { label: 'Lord of the Rings', data: window.LOTR_DATA },
  marvel: { label: 'Marvel', data: window.MARVEL_DATA },
};
// The sets in play (one or more, for mash-ups), and DATA: their cards merged, each tagged with
// its set's name (`set`). Decks are still built set by set (buildFromSets) so a card's back
// names come from its own set.
const DEFAULT_SETS = ['bladerunner'];
let SETS = DEFAULT_SETS;
let DATA = mergeSets(SETS);
function mergeSets(keys) {
  const base = window.GAME_DATA;
  const sets = keys.map(k => ({ key: k, set: THEMES[k].label, d: THEMES[k].data }));
  const group = name => ({ icons: base[name].icons, cards: sets.flatMap(({ set, d }) => d[name].cards.map(c => ({ ...c, set, icons: d[name].icons }))) });
  return {
    approaches: base.approaches, resources: base.resources, players: base.players, sets,
    situations: sets.flatMap(({ set, d }) => d.situations.map(s => ({ ...s, set }))),
    banes: sets.flatMap(({ set, d }) => (d.banes || []).map(b => ({ ...b, set }))),
    macguffins: group('macguffins'), allies: group('allies'), villains: group('villains'), locations: group('locations'),
  };
}
// One deck from every set in play: `build(setData, setKey)` makes a set's cards, which are tagged and shuffled together.
const buildFromSets = build => shuffle(DATA.sets.flatMap(({ key, set, d }) => build(d, key).map(c => ({ ...c, set }))));
const buildBoonDeck = () => buildFromSets(d => buildPcDeck('boon', d.boons, d.boonStates, '➕', 1));
// The set a card comes from, in small faint text at the very bottom of its face.
const setTag = card => (card && card.set ? `<div class="set-tag">${esc(card.set)}</div>` : '');
const APPROACHES = window.GAME_DATA.approaches;
// The approaches' names, small and in capitals under their icons on cards and dice.
const APPROACH_NAMES = ['Bold', 'Wise', 'Calm', 'Loud', 'Swift', 'Subtle']; // in APPROACHES order
const approachName = a => APPROACH_NAMES[APPROACHES.findIndex(x => x.replace(/️/g, '') === (a || '').replace(/️/g, ''))] || '';
const approachTag = a => `<span class="ap-icon" data-ap="${noVS16(a)}">${a}<span class="ap-name">${approachName(a)}</span></span>`;
const approachFace = a => approachTag(a); // an approach die's face
// The six resources on the character sheet. A failure costs the row's resource ("Lost Momentum"),
// and the approach used changes how much (Cost vs. Approaches): `good` guards it, `bad`
// squanders it. Information/Reputation are a pair (🕶️ vs 📢); the other four go round a loop where
// each approach guards one resource and squanders the next.
const RISKS = {
  'ℹ️': { name: 'Information', good: '🕶️', bad: '📢' },     // Revealed
  '⭐': { name: 'Reputation', good: '📢', bad: '🕶️' }, // Unaware
  '📦': { name: 'Resources', good: '🧠', bad: '⚡' },  // Wasted
  '🔥': { name: 'Motivation', good: '💪', bad: '🧠' },     // Ineffective
  '📏': { name: 'Control', good: '🐢', bad: '💪' },    // Spillover
  '⌛': { name: 'Momentum', good: '⚡', bad: '🐢' },       // Delayed
};
const RESOURCES = Object.keys(RISKS);
// A resource as shown on the Situation cards and character sheets: the approach that guards it (+1)
// under a 🔺, the one that squanders it (−1) under a 🔻, and its name underneath.
// Just the resource's name in its coloured box (as on the Concept and Trouble cards).
const resourceLabel = res => `<span class="res-name res-${RESOURCES.indexOf(res)}">${esc(RISKS[res].name)}</span>`;
// `cols`: each side in its own column box (.res-col.good / .bad), so one can be lit up (the risk tiles).
function resourceBadge(res, note = '', cols = false) {
  const r = RISKS[res];
  const grid = cols
    ? `<span class="res-grid res-cols"><span class="res-col good"><span class="res-arrow">🔺</span><span>${r.good}</span></span><span class="res-col bad"><span class="res-arrow">🔻</span><span>${r.bad}</span></span></span>`
    : `<span class="res-grid"><span class="res-arrow">🔺</span><span class="res-arrow">🔻</span><span>${r.good}</span><span>${r.bad}</span></span>`;
  return `<span class="res-badge" title="${esc(r.name)}">${grid}${resourceLabel(res)}${note}</span>`;
}
const noVS16 = s => (s || '').replace(/️/g, ''); // emoji variation selectors vary between sources
// What a failure costs with `approach` on a row that risks `risk`: 0, 1 or 2 (always 1 when
// rows have a fixed approach).
function riskCost(risk, approach) {
  const r = RISKS[risk];
  if (!SIM_RULES.freeApproach || !r || SIM_RULES.riskModifier) return 1;
  if (noVS16(approach) === noVS16(r.good)) return 0;
  if (noVS16(approach) === noVS16(r.bad)) return 2;
  return 1;
}
const riskName = risk => (RISKS[risk] ? RISKS[risk].name : risk);
const PLAYER_COLORS = ['#e0aa1b', '#3a7bd5', '#d64545', '#3fa66b'];
const RESOURCE_START = 2; // +1 if the Concept names the resource, -1 if the Trouble does (SIM_RULES.resourceStart overrides)

// Character cards (Concept, Trouble, Asset, Liability, Relationship) are the size of a Fate card.
const PC_CARD = { w: 150, h: 210 };
const DIE_SIZE = 72; // every die on the table: the sheets' resource dice and all the approach dice
// Element cards: MacGuffin, Ally and Villain side by side, and underneath them the Location:
// as wide as the Situation card, shaped like an index card (5 x 3), its nine lines in two
// columns. Text is as large as the Situation card's.
const EL_CARD = { w: 310, h: Math.round(310 * 88 / 63) }; // wide enough for two name cards side by side; Magic card proportions (63 x 88)
const EL_GAP = 20;
// The Location card: landscape, in two columns (the title and four lines, then five lines from the top).
// The Situation card turned landscape (SIT_CARD is set further down, so read it when used).
const LOC_CARD = { get w() { return SIT_CARD.h; }, get h() { return SIT_CARD.w; } };
const elSize = kind => (kind === 'location' ? LOC_CARD : EL_CARD);
const PEEK = 44; // how much of a tucked name card shows above the card it's under
const STACK_STEP = PC_CARD.h + 8; // a second Asset / Liability sits right under the first

// ---------------------------------------------------------------------------
// Decks
// ---------------------------------------------------------------------------

function pickApproaches(n) {
  return shuffle(APPROACHES).slice(0, n);
}

// Every card in a double-sided deck gets two names on its back, one at each end.
// With fewer names than spots, each name appears twice across the deck, never twice on
// the same card.
function pairNames(names, count) {
  // Enough names for every back (e.g. place words): use each one once.
  if (names.length >= count * 2) {
    const all = shuffle(names);
    return Array.from({ length: count }, (_, i) => [all[i * 2], all[i * 2 + 1]]);
  }
  const a = shuffle(names), b = shuffle(names);
  for (let i = 0; i < b.length; i++) {
    if (b[i] === a[i]) {
      const j = (i + 1) % b.length;
      [b[i], b[j]] = [b[j], b[i]];
    }
  }
  return Array.from({ length: count }, (_, i) => [a[i % a.length], b[i % b.length]]);
}

// Concept and Trouble cards also name a resource, which raises or lowers its starting value.
// The spreadsheet doesn't assign these yet, so they're random per deal.
function buildPcDeck(kind, texts, backNames, sign, nApproaches, withResource = false) {
  const names = pairNames(backNames, texts.length);
  return shuffle(texts).map((text, i) => ({
    kind, text, sign,
    approaches: pickApproaches(nApproaches),
    resource: withResource ? RESOURCES[randInt(RESOURCES.length)] : null,
    names: names[i],
  }));
}

function buildElementDeck(kind, label, group, backNames) {
  const names = backNames ? pairNames(backNames, group.cards.length) : [];
  return shuffle(group.cards).map((card, i) => ({
    kind,
    label,
    icons: group.icons,
    name: card.name,
    // Every attribute line gets a random approach, as on the Main sheet.
    lines: card.lines.map(text => ({ text, approach: APPROACHES[randInt(APPROACHES.length)] })),
    names: names[i],
  }));
}

// ---------------------------------------------------------------------------
// Card faces
// ---------------------------------------------------------------------------

const KIND_LABEL = { concept: 'Concept', trouble: 'Trouble', boon: 'Asset', bane: 'Liability', relationship: 'Relationship' };

// The player reference card, two-sided and as big as an Ally / Villain / Object card: the round on
// one side, a roll on the other.
function refRoundSide() {
  return `
    <div class="ref-title"><span class="ref-kind">Player reference</span>Each round</div>
    <ol class="ref-steps">
      <li><b>Obstacle.</b> The Storyteller sets it on a row and an approach: that approach’s bonuses don’t count there.</li>
      <li><b>Moves</b>, in initiative order: <b>Main</b> on a free row (choose your approach) · <b>Help</b> a Main (a Relationship beside you shows their approach) · <b>Clear seat</b> · <b>Pass</b>.</li>
      <li><b>Compel.</b> The Storyteller may compel one Main’s ✖️ Trouble or ➖ Liability: −1 and +1 Story Point, or refuse for 1.</li>
      <li><b>Fate.</b> Turn one card for everyone.</li>
      <li><b>Rolls</b>, in initiative order (see the back).</li>
      <li><b>Clear seat:</b> remove a Tension die, +1 Story Point, go first next round.</li>
      <li><b>End.</b> A row emptied? The situation is won. Least spotlight goes first next round.</li>
    </ol>`;
}
function refRollSide() {
  const signed = n => (n > 0 ? `+${n}` : `${n}`.replace('-', '−'));
  return `
    <div class="ref-title"><span class="ref-kind">Player reference</span>Your roll</div>
    <ul class="ref-list">
      <li><span>✔️ Concept · ➕ each Asset</span><b>+1</b></li>
      <li><span>Edge die · each helper</span><b>+1</b></li>
      <li><span>Row’s 🔺 / 🔻</span><b>+1 / −1</b></li>
      <li><span>Each Tension die · a compel</span><b>−1</b></li>
      <li><span>Fate card</span><b>−2 to +2</b></li>
      <li><span>After Fate: Story Points, resource points</span><b>+1 each, up to ${SIM_RULES.maxEdgePerBet || 2} + ${SIM_RULES.maxPushPerRoll || 2}</b></li>
    </ul>
    <div class="ref-sub">Margin over the difficulty</div>
    <ul class="ref-list ref-results">
      <li><span><b>Epic Failure</b>: a Liability, and an Escalation</span><b>${signed(-SIM_RULES.failBy)} or less</b></li>
      ${SIM_RULES.failBy > 1 ? `<li><span><b>Failure</b>: nothing happens</span><b>${signed(1 - SIM_RULES.failBy)} to 0</b></li>` : `<li><span><b>Failure</b>: nothing happens</span><b>0</b></li>`}
      <li><span><b>Success</b>: take a spotlight token</span><b>+1</b></li>
      <li><span><b>Epic Success</b>: a token and an Asset</span><b>+${SIM_RULES.boonMargin} or more</b></li>
    </ul>`;
}

function pcFront(card) {
  const sign = card.sign || (card.kind === 'relationship' ? '👥' : ''); // shown beside the card's type
  return `
    <div class="kind-label">${sign ? `<span class="sign">${sign}</span>` : ''}${KIND_LABEL[card.kind]}</div>
    <div class="pc-text${card.text.length > 30 ? ' long' : ''}">${esc(card.text)}</div>
    <div class="approach-row">${card.approaches.map(a => (card.kind === 'relationship' ? `<span class="ap-rel" data-ap="${noVS16(a)}">${a}</span>` : approachTag(a))).join('')}${card.resource ? `<span class="resource">${resourceBadge(card.resource)}</span>` : ''}</div>${setTag(card)}`;
}

function namesBack(label, names) {
  const end = (name, extra = '') => `<div class="name-end ${name.length > 13 ? 'long' : ''} ${extra}">${esc(name)}</div>`;
  return `
    ${end(names[0])}
    <div class="back-emblem"><span>✦</span><small>${esc(label)}</small></div>
    ${end(names[1], 'upside-down')}`;
}

function portraitBack(portrait) {
  return `
    <div class="portrait" style="background:${portrait.bg}">${portrait.svg}</div>
    <div class="back-strip">Relationship</div>`;
}

// ---- Fate deck ----
// Drawn when testing an approach: each card gives a modifier for all six approaches.
// Across the deck, every approach gets each of -2..+2 equally often.

const FATE_VALUES = [-2, -1, 0, 1, 2];
const FATE_DECK_SIZE = 30; // 6 of each value per approach
const FATE_CARD = { w: 150, h: 210 };
// Balanced deck (SIM_RULES.fateDeck 'balanced', 2026-10-18): every card shows −2, −1, 0, 0, +1, +2,
// one per approach, and across each set of 6 cards every approach gets those same six values
// once each. 24 cards = 4 differently shuffled sets. 'random': the old 30-card deck above, where
// a card can favour everyone or no one.
const FATE_CARD_VALUES = [-2, -1, 0, 0, 1, 2];
const FATE_BALANCED_SETS = 4;

function buildFateDeck() {
  if (SIM_RULES.fateDeck === 'balanced') {
    const cards = [];
    for (let set = 0; set < FATE_BALANCED_SETS; set++) {
      // Shift a shuffled row of the six values one place per card (a Latin square), with the
      // approaches in a shuffled order: each card and each approach gets all six values once.
      const row = shuffle(FATE_CARD_VALUES);
      const order = shuffle(APPROACHES.map((_, a) => a));
      for (let k = 0; k < FATE_CARD_VALUES.length; k++) {
        cards.push(APPROACHES.map((approach, a) => ({ approach, value: row[(order[a] + k) % row.length] })));
      }
    }
    return shuffle(cards);
  }
  const copies = FATE_DECK_SIZE / FATE_VALUES.length;
  const columns = APPROACHES.map(() => shuffle(FATE_VALUES.flatMap(v => Array(copies).fill(v))));
  return Array.from({ length: FATE_DECK_SIZE }, (_, c) =>
    APPROACHES.map((approach, a) => ({ approach, value: columns[a][c] })));
}

function fateFront(card) {
  const fmt = v => (v > 0 ? `+${v}` : v < 0 ? `\u2212${-v}` : '0');
  const tone = v => (v > 0 ? 'up' : v < 0 ? 'down' : '');
  return `<div class="fate-grid">${card.map(({ approach, value }) => `
    <div class="fate-cell"><span class="fate-approach">${approach}</span><span class="fate-value ${tone(value)}">${fmt(value)}</span></div>`).join('')}
  </div>`;
}

function plainBack(label) {
  return `<div class="back-emblem"><span>✦</span><small>${esc(label)}</small></div>`;
}

// What each Element line is, by its icon: a small label over the line's text on the card.
const LINE_NAMES = {
  '💎': 'Material', '📍': 'Where it’s from', '✨': 'What it’s for', '❌': 'Its flaw',          // Object
  '👻': 'Fear', '🚩': 'Goal', '🔒': 'Secret', '🔗': 'Connection',                             // Ally, Villain
  '🪜': 'Climb', '🧱': 'Cover', '🕳': 'Pit', '🌉': 'Crossing', '🪨': 'Obstacle',               // Location
  '🚪': 'Hidden entry', '💦': 'Slick', '⚠': 'Hazard', '💀': 'Enemies',
};
const lineName = icon => LINE_NAMES[noVS16(icon)] || '';

function elementFront(card) {
  const [headIcon, ...lineIcons] = card.icons;
  const head = `<div class="el-head"><span class="el-icon">${headIcon}</span><span class="el-title"><span class="el-type">${esc(card.label)}</span><span class="el-name${card.name.length > 18 ? ' long' : ''}">${esc(card.name)}</span></span></div>`;
  const items = (from, to) => card.lines.slice(from, to).map((line, k) => {
    const i = from + k;
    return `
        <li data-line="${i}"><span class="el-body"><span class="el-label">${esc(lineName(lineIcons[i] || ''))}</span><span class="el-text">${esc(line.text)}</span></span><span class="el-approach">${approachTag(line.approach)}</span></li>`;
  }).join('');
  // The Location: two columns over the whole card, the title and its first lines on the left and
  // the rest on the right, from the top.
  if (card.kind === 'location') {
    const left = Math.floor(card.lines.length / 2);
    return `
    <div class="loc-col">${head}<ul class="el-lines">${items(0, left)}</ul></div>
    <div class="loc-col"><ul class="el-lines">${items(left)}</ul></div>${setTag(card)}`;
  }
  return `${head}<ul class="el-lines">${items(0)}</ul>${setTag(card)}`;
}

// ---------------------------------------------------------------------------
// Placing things
// ---------------------------------------------------------------------------

function label(text, x, y, className = 'section-label') {
  return addStatic(el('div', className, esc(text)), x, y);
}

// ---- Pile counts ----
// A pile's label shows how many tokens are in it, e.g. "Edge (3)". Tokens are counted by
// where they lie (`rect`, in world coordinates), so hand moves count as well as the simulator's.
let pileLabels = [];

function countedLabel(text, x, y, className, tokenClass, rect) {
  const node = label(text, x, y, className);
  pileLabels.push({ node, text, tokenClass, rect });
  queuePileCounts();
  return node;
}

function updatePileCounts() {
  pileLabels = pileLabels.filter(p => p.node.isConnected);
  for (const { node, text, tokenClass, rect: r } of pileLabels) {
    const n = pieces.filter(t => {
      if (!t.el.classList.contains(tokenClass)) return false;
      const cx = t.x + t.w / 2, cy = t.y + t.h / 2;
      return cx >= r.x && cx <= r.x + r.w && cy >= r.y && cy <= r.y + r.h;
    }).length;
    node.innerHTML = `${esc(text)} <span class="pile-count">(${n})</span>`;
  }
}

let pileCountQueued = false;
function queuePileCounts() {
  if (pileCountQueued) return;
  pileCountQueued = true;
  queueMicrotask(() => { pileCountQueued = false; updatePileCounts(); });
}
window.onPieceMoved = queuePileCounts;

function placePcCard(card, x, y, faceUp = true) {
  let back = card.kind === 'relationship' ? portraitBack(card.portrait)
    : card.names && card.kind !== 'boon' ? namesBack(KIND_LABEL[card.kind], card.names) : plainBack(KIND_LABEL[card.kind]); // an Asset has no names on its back
  const { w, h } = PC_CARD;
  back += setTag(card); // the set's name on the back too
  const piece = createCard({
    className: `pc-card kind-${card.kind}`,
    w, h, x, y, faceUp,
    front: pcFront(card),
    back,
  });
  piece.card = card;
  piece.cardKind = card.kind;
  return piece;
}

// ---- Invoking element lines (switched off for now) ----
// Once per situation, a player can invoke a line on a Location / Villain / Ally / MacGuffin
// card for +1 to a roll using that line's approach. Tap a line to mark it used.
// Off because reading the small card lines mid-bet is too fiddly; set true to try again.
const INVOKE_LINES = false;

function setLineUsed(piece, i, used) {
  piece.usedLines = piece.usedLines || new Set();
  if (used) piece.usedLines.add(i); else piece.usedLines.delete(i);
  const li = piece.el.querySelector(`.el-lines li[data-line="${i}"]`);
  if (li) li.classList.toggle('used', used);
}

function elementCards() {
  return pieces.filter(p => p.card && p.card.lines && ['macguffin', 'ally', 'villain', 'location'].includes(p.cardKind) && !p.parent);
}

function resetElementLines() {
  elementCards().forEach(p => (p.usedLines ? [...p.usedLines] : []).forEach(i => setLineUsed(p, i, false)));
}

function placeElementCard(card, x, y, faceUp = true) {
  const { w, h } = elSize(card.kind);
  const piece = createCard({
    className: `el-card kind-${card.kind}`,
    w, h, x, y, faceUp,
    front: elementFront(card),
    back: (card.names ? namesBack(card.label, card.names) : plainBack(card.label)) + setTag(card),
  });
  piece.card = card;
  piece.cardKind = card.kind;
  if (INVOKE_LINES) piece.tapHandler = target => {
    const li = target.closest && target.closest('.el-lines li[data-line]');
    if (!li || !piece.faceUp) return false;
    const i = +li.dataset.line;
    setLineUsed(piece, i, !(piece.usedLines && piece.usedLines.has(i)));
    return true;
  };
  return piece;
}

// Names already showing this deal. Every name is printed on two cards, so avoid repeats.
const shownNames = new Set();

// Draw a spare card from `deck` to use as a name card, and pick which end (name) shows:
// one not already on the table if possible.
// An even mix of the sets in play: each deck's draws take turns between its sets, in a random order
// per deck (so with 2 sets and 4 players, 2 Concepts come from each, and 2 Troubles from each).
// Name cards (drawNameCard) still come from whatever is left.
function drawEven(deck) {
  if (!deck.turns) { deck.turns = shuffle([...new Set(deck.map(c => c.set))]); deck.turn = 0; }
  for (let k = 0; k < deck.turns.length; k++) {
    const want = deck.turns[(deck.turn + k) % deck.turns.length];
    const i = deck.map(c => c.set).lastIndexOf(want);
    if (i >= 0) { deck.turn = (deck.turn + k + 1) % deck.turns.length; return deck.splice(i, 1)[0]; }
  }
  return deck.pop();
}
// The last card in `deck` from set `want` (or just the last card).
function drawFromSet(deck, want) {
  const i = deck.map(c => c.set).lastIndexOf(want);
  return i >= 0 ? deck.splice(i, 1)[0] : deck.pop();
}

function drawNameCard(deck) {
  let idx = deck.length - 1;
  for (let i = deck.length - 1; i >= 0; i--) {
    if (deck[i].names.some(n => !shownNames.has(n))) { idx = i; break; }
  }
  const [card] = deck.splice(idx, 1);
  const ends = shuffle([0, 1]);
  const end = ends.find(i => !shownNames.has(card.names[i])) ?? ends[0];
  shownNames.add(card.names[end]);
  return { card, rot: end * 180 };
}

// Flip a spare card and tuck it under `main` with one name peeking out above it.
// Long-press the tucked card to turn it around.
function tuckNameCard(main, deck, place) {
  const { card, rot } = drawNameCard(deck);
  const tucked = place(card, main.x, main.y - PEEK, false);
  tucked.rot = rot;
  setPos(tucked);
  raise(main);
  attach(main, tucked);
  return tucked;
}

// ---- Snap zones ----

const NAME_LABEL = { concept: 'First name', trouble: 'Last name' };

function zoneOutline(x, y, w, h, text, rot = 0, extra = '') {
  const node = el('div', `zone ${extra}`, text ? `<span>${esc(text)}</span>` : '');
  node.style.width = `${w}px`;
  node.style.height = `${h}px`;
  if (rot) node.style.transform = `rotate(${rot}deg)`;
  return addStatic(node, x, y);
}

// A character card slot, with a name slot above it for the tucked name card.
function cardSlot(kind, x, y) {
  const { w, h } = PC_CARD;
  const main = addZone({ accepts: kind, x, y, w, h });
  if (NAME_LABEL[kind]) main.nameZone = addZone({
    accepts: kind, tucked: true, parentZone: main, x, y: y - PEEK, w, h,
    el: zoneOutline(x, y - PEEK, w, PEEK, NAME_LABEL[kind], 0, 'name-zone'),
  });
  main.el = zoneOutline(x, y, w, h, KIND_LABEL[kind]);
  // The Concept's and Trouble's places on the player board: their sign and name, large.
  if (kind === 'concept' || kind === 'trouble') {
    main.el.classList.add('card-place');
    main.el.innerHTML = `<span class="place-sign">${kind === 'concept' ? '✔️' : '✖️'}</span><span class="place-name">${KIND_LABEL[kind]}</span>`;
  }
  return main;
}

// Deal a card into a slot, plus a flipped spare from the same deck as its name card.
function dealIntoSlot(zone, deck) {
  const main = placePcCard(drawEven(deck), zone.x, zone.y);
  snapTo(main, zone, false);
  const { card, rot } = drawNameCard(deck);
  const name = placePcCard(card, zone.x, zone.y - PEEK, false);
  name.rot = rot;
  snapTo(name, zone.nameZone, false);
  name.el.classList.add('tucked-name'); // slides under the player board, only its name above the edge
  return main;
}

// Character sheet: three resource columns, two rows. Each resource has a small label (icon, then
// name) above its box, and a d6 in the box showing the current value. The Concept and Trouble
// sit side by side above the sheet.
const SHEET_COL = 110;     // one resource column: the box hugs its die, with room either side
const SHEET_COLS = [SHEET_COL, SHEET_COL, SHEET_COL];
// Just the six resources, in two rows. Each resource cell is its label plus a box just taller than
// the die.
const SHEET_LABEL = 62, SHEET_ROW = 80, SHEET_GAP = 10, SHEET_PAD = 3;
const SHEET_CELL = SHEET_LABEL + SHEET_ROW;
const SHEET_W = SHEET_COLS.reduce((a, b) => a + b, 0) + SHEET_PAD * 2;
const SHEET_PAD_Y = 6; // above and below the rows
const SHEET_H = 2 * SHEET_CELL + SHEET_GAP + 2 * SHEET_PAD_Y;
const SHEET_LAYOUT = [['ℹ️', '⭐', '📦'], ['🔥', '📏', '⌛']]; // three per row
// The Concept and Trouble, side by side and centred over the sheet: their left edges.
const PAIR_GAP = 6;
const conceptX = sheetX => sheetX + (SHEET_W - 2 * PC_CARD.w - PAIR_GAP) / 2;
const troubleX = sheetX => conceptX(sheetX) + PC_CARD.w + PAIR_GAP;

function buildSheet(x, y, concept, trouble) {
  const sheet = el('div', 'sheet');
  sheet.style.gridTemplateColumns = SHEET_COLS.map(c => `${c}px`).join(' ');
  sheet.style.gridTemplateRows = `repeat(2, ${SHEET_CELL}px)`;
  sheet.style.paddingTop = sheet.style.paddingBottom = `${SHEET_PAD_Y}px`;
  sheet.style.paddingLeft = sheet.style.paddingRight = `${SHEET_PAD}px`;
  sheet.style.rowGap = `${SHEET_GAP}px`;
  sheet.style.width = `${SHEET_W}px`;
  SHEET_LAYOUT.forEach(trio => trio.forEach(res => sheet.append(el('div', 'sheet-cell',
    `<div class="sheet-label">${resourceBadge(res)}</div><div class="sheet-box res-box res-${RESOURCES.indexOf(res)}"></div>`))));
  addStatic(sheet, x, y);

  // The middle of a resource's box (under its label).
  const boxCenter = (row, col) => ({
    x: x + SHEET_PAD + col * SHEET_COL + SHEET_COL / 2,
    y: y + SHEET_PAD_Y + row * (SHEET_CELL + SHEET_GAP) + SHEET_LABEL + SHEET_ROW / 2,
  });
  const DIE = DIE_SIZE;
  const dice = {};
  SHEET_LAYOUT.forEach((trio, row) => trio.forEach((res, k) => {
    const value = (SIM_RULES.resourceStart ?? RESOURCE_START) + (concept?.resource === res) - (trouble?.resource === res);
    const c = boxCenter(row, k);
    dice[res] = createDie({ className: 'die-sheet', size: DIE, value: Math.max(1, Math.min(6, value)), x: c.x - DIE / 2, y: c.y - DIE / 2 });
  }));
  return dice;
}

// The A/B/C board: a difficulty banner, then Main | Help | Approach | Minus | Risk | Successes.
// Its banner + headings are exactly as tall as the Situation card's opening text, so the
// board's rows sit level with the card's choices A, B and C beside it.
// Risk comes first (next to the Situation card's choices), then the row's shape, who acts, and
// the Tension. With
// freeApproach there's no Approach column (the Main player picks), and the Risk column is
// wider: it names the resource and which approaches guard or squander it.
// The first column is a slot cut into the Board: the Situation card slides in so its three
// choices (with their risks) sit in it, level with rows A, B and C.
// Main and Help hold pawns (round spots); Approach holds the Main's own approach die and Edge the
// Edge die (the Situation's bonus die) when the Main claims it.
const MAT_COL_NAMES = ['main', 'help', 'approach', ...(SIM_RULES.sceneModifier && SIM_RULES.sceneClaim ? ['edge'] : []), 'minus', ...(SIM_RULES.obstacle ? ['obstacle'] : []), 'successes'];
const MAT_COL_W = { main: 104, help: 104, approach: 102, edge: 102, minus: 104, obstacle: 104, successes: 124 };
const MAT_COLS = MAT_COL_NAMES.map(n => MAT_COL_W[n]);
const matCol = name => MAT_COL_NAMES.indexOf(name);
// The Board is as tall as the upright Situation card beside it, top and bottom level with it: the
// banner fills the card's description and the footer its Escalations, so the rows line up.
const MAT_BANNER = 136, MAT_HEAD = 26, MAT_ROW = 104, MAT_FOOT = 147, MAT_PAD = 8;
const MAT_W = MAT_COLS.reduce((a, b) => a + b, 0) + MAT_PAD * 2;
const MAT_TOP = MAT_PAD + MAT_BANNER + MAT_HEAD; // where row A starts

// The banner across the top of the Board: what wins a situation, and a small table of the
// per-act numbers for this player count (the current act is highlighted during play).
function boardRulesHtml(players) {
  const acts = [...new Set(SIM_RULES.acts)]; // one column per kind of act (all Middles alike)
  // Resource points each player gets back before every act after the first (1 at 2 players, 2 at 3-4).
  // (Everyone's 1 Story Point at the start of the game goes without saying, so it isn't shown.)
  const heal = playerRule('actEndHeal', players);
  const bonus = playerRule('actWinBonus', players);
  const row = (label, cell) => `<tr><th>${label}</th>${acts.map(a => `<td data-act="${a}">${cell(a)}</td>`).join('')}</tr>`;
  const perAct = typeof playerRule('target', players) === 'object'; // stacks that grow each act
  return `
    <div class="mat-goal">
      <div>${perAct ? 'The successes in the table win a row' : `<b>${playerRule('target', players)}</b> successes on a row win`}</div>
      <div class="mat-sub">${players} players · miss by ${SIM_RULES.failBy}+ to fail${SIM_RULES.minorFailure ? ' · by 1: lose the resource' : ''}</div>
      <div class="mat-scene"></div>
    </div>
    <table class="mat-rules">
      <tr><th></th>${acts.map(a => `<th data-act="${a}">${a}</th>`).join('')}</tr>
      ${perAct ? row('Successes', a => actTarget(a, players)) : ''}
      ${row('Difficulty', a => playerRule('difficulty', players)[a])}
      ${heal ? row('Resources back first', a => (a === acts[0] ? '—' : `+${heal}`)) : ''}
      ${row(acts.some(a => bonus[a].helper) ? 'Win bonus <small>(helper)</small>' : SIM_RULES.actWinBonusAs === 'storyPoints' ? 'Winner’s Story Pts' : 'Win bonus', a => `${bonus[a].main}${bonus[a].helper ? ` <small>(${bonus[a].helper})</small>` : ''}`)}
    </table>`;
}

// Highlight the act being played in the Board's rules table (null clears it).
function highlightBoardAct(act) {
  document.querySelectorAll('.mat-rules [data-act]').forEach(c => c.classList.toggle('now', c.dataset.act === act));
}

function buildMat(x, y, situation) {
  const mat = el('div', 'mat');
  mat.style.gridTemplateColumns = MAT_COLS.map(c => `${c}px`).join(' ');
  mat.style.gridTemplateRows = `${MAT_BANNER}px ${MAT_HEAD}px repeat(3, ${MAT_ROW}px) ${MAT_FOOT}px`;
  mat.appendChild(el('div', 'mat-banner', boardRulesHtml(Math.min(PLAYER_COUNT, DATA.players.length))));
  // Each column's title on top, and a reminder of its rules under the column.
  const players = Math.min(PLAYER_COUNT, DATA.players.length);
  const miniEdge = '<span class="mini-tok edge" title="Story Points">+1</span>';
  const miniSpot = '<span class="mini-tok spot" title="spotlight">★</span>';
  const miniFirst = '<span class="mini-tok init" title="initiative">1</span>';
  const heads = {
    main: ['Main', `${SIM_RULES.rowOrder === 'initiative' ? 'rolls in initiative order<br>' : ''}${SIM_RULES.maxStake ? `stake up to ${SIM_RULES.maxStake} ${miniSpot} · ` : ''}${SIM_RULES.maxEdgePerBet ? `Story Points: up to ${SIM_RULES.maxEdgePerBet}` : 'spend any Story Points'}${(PLAYER_COUNT_RULES[players] || {}).endingEdgeCap ? ` (Ending ${PLAYER_COUNT_RULES[players].endingEdgeCap})` : ''} ${miniEdge}`],
    help: ['Help', '+1 each · needs a matching Relationship'],
    approach: ['Approach', SIM_RULES.freeApproach ? 'the Main’s own die, set to how they go in' : 'read it on the Fate card'],
    edge: ['Edge', `${sceneMod()}: the first Main going in with its approach takes the Edge die`],
    minus: ['Tension', `−1 to its approach${SIM_RULES.minusNextRound ? '<br>from next round' : ''}<br>2 out: a fail loses${SIM_RULES.clearTiming === 'end' ? `<br>Clear: ${miniEdge}${SIM_RULES.clearGoesFirst ? ` ${miniFirst}st` : ''}` : ''}`],
    obstacle: ['Obstacle', `${SIM_RULES.obstacleCancels ? 'its approach gets<br>no bonuses' : '−1 to its approach'}<br>on its row only<br>set by the Storyteller`],
    successes: ['Successes', `${typeof playerRule('target', players) === 'object' ? 'stack in the table' : playerRule('target', players)} to win${SIM_RULES.overflowAtRowLimit ? `<br>extra margin → ${miniEdge}` : ''}`],
  };
  MAT_COL_NAMES.forEach(c => mat.appendChild(el('div', 'mat-head', heads[c][0])));
  // Minus dice come from Escalations and hit every roll, so it's one tall box for all three
  // rows (added on row A only): the dice at the top, and a pawn clearing one of them at the bottom.
  const cellFor = {
    main: () => el('div', 'mat-cell round'),
    help: () => el('div', 'mat-cell help round'),
    approach: () => el('div', 'mat-cell approach'),
    edge: () => el('div', 'mat-cell edge'),
    minus: row => (row === 0 ? el('div', 'mat-cell minus') : null),
    obstacle: () => el('div', 'mat-cell obstacle'),
    successes: () => el('div', 'mat-cell'),
  };
  [0, 1, 2].forEach(row => MAT_COL_NAMES.forEach(c => { const node = cellFor[c](row); if (node) mat.appendChild(node); }));
  MAT_COL_NAMES.forEach(c => mat.appendChild(el('div', `mat-foot foot-${c}`, heads[c][1])));
  addStatic(mat, x, y);

  // Centre of a cell, in world coordinates.
  return (row, col) => ({
    x: x + MAT_PAD + MAT_COLS.slice(0, col).reduce((a, b) => a + b, 0) + MAT_COLS[col] / 2,
    y: y + MAT_TOP + row * MAT_ROW + MAT_ROW / 2,
  });
}

// The Situation card stands upright left of the Board: the description at the top, the three
// choices in the middle (each a Board row tall, level with the Board's rows), the Escalations
// at the bottom.
const SIT_CARD = { w: 400, border: 5, intro: 165, escs: 150 }; // intro: the .sit-intro height in style.css
SIT_CARD.h = 2 * SIT_CARD.border + SIT_CARD.intro + 3 * MAT_ROW + SIT_CARD.escs;

// One size for the A/B/C shapes on the Board and on the Situation card.
const ROW_SHAPE_SIZE = 25;

// A, B and C each have a shape, on the Board and on the Situation card: triangle, square, circle.
function rowShape(i, size = 34) {
  const shape = [
    '<polygon points="50,4 97,92 3,92"/>',
    '<rect x="7" y="7" width="86" height="86" rx="12"/>',
    '<circle cx="50" cy="50" r="46"/>',
  ][i];
  return `<svg class="row-shape row-shape-${i}" viewBox="0 0 100 100" width="${size}" height="${size}" aria-hidden="true">${shape}<text x="50" y="${i === 0 ? 76 : 66}" text-anchor="middle">${'ABC'[i]}</text></svg>`;
}

// `result` (optional): { row: 0-2, name, color } for the character who won it, or
// { lost: true }. Shown as a stamp so finished situations can be re-enacted later.
// The card is a fixed size and its text one fixed size (see style.css), so it fits as is.

// "… 🐢 (⌛)" at the end of a choice: the approach and the risk. Both are dropped from the text:
// the risk (and, with freeApproach, its ✓ / ✗ approaches) is drawn beside the choice instead.
const APPROACH_AND_RISK = new RegExp(`\\s*(?:(?:${APPROACHES.map(a => noVS16(a) + '\\uFE0F?').join('|')})\\s*)?\\([^)]*\\)\\s*$`, 'u');
function choiceRiskHtml(risk) {
  if (SIM_RULES.riskDraw) return '<span class="sit-risk-slot"></span>'; // the round's risk tile lies here
  const r = RISKS[risk];
  if (!r) return '';
  // Risks as bonuses: +1 / −1 approaches on the left, the resource and what a failure costs right.
  if (SIM_RULES.riskModifier && SIM_RULES.freeApproach) {
    // One right-aligned column: the row's resource (icon, then name, as on the character sheets), then +1 with the approach that
    // guards it and −1 with the one that squanders it; the emoji line up down the right edge.
    return `<span class="sit-risk mod badge">${resourceBadge(risk, SIM_RULES.failLiabilityOnly ? '' : ' <span class="sit-risk-fail">(fail: −1)</span>')}</span>`;
  }
  return `<span class="sit-risk" title="Lost ${esc(r.name)}">`
    + (SIM_RULES.freeApproach ? `<span class="sit-risk-side"><b class="good">✓</b>${r.good}</span>` : '')
    + `<span class="sit-risk-icon">${risk}</span>`
    + (SIM_RULES.freeApproach ? `<span class="sit-risk-side"><b class="bad">✗</b>${r.bad}</span>` : '')
    + '</span>';
}

// The Situation card as a mad lib: each Element symbol is a blank with what goes there written
// small underneath ("Villain", "Villain’s Goal", "Crossing"); the read-aloud text fills them in.
const KIND_NAMES = { villain: 'Villain', ally: 'Ally', macguffin: 'Object', location: 'Location' };
function madLibKeys() {
  const keys = [];
  const groups = { villain: DATA.villains, ally: DATA.allies, macguffin: DATA.macguffins, location: DATA.locations };
  for (const [kind, group] of Object.entries(groups)) {
    if (!group || !group.icons) continue;
    const [head, ...lines] = group.icons.map(noVS);
    lines.forEach(icon => {
      keys.push({ key: head + icon, label: `${KIND_NAMES[kind]}’s ${lineName(icon)}` });
      if (kind === 'location') keys.push({ key: icon, label: lineName(icon) }); // a feature alone is the Location's
    });
    keys.push({ key: head, label: KIND_NAMES[kind] });
  }
  keys.push({ key: noVS('🏠'), label: 'Location' }); // situations use 🏠 for any location
  return keys.sort((a, b) => b.key.length - a.key.length); // pairs first
}
// Each blank is filled in, in green on its line, with what the dealt cards say goes there (as the
// read-aloud text does); `words` are the ones an act was played with, else the table's now, and
// `seen` is shared across a card so a person's title is only given the first time.
function madLib(text, words = null, seen = new Set()) {
  const src = noVS(text || ''), keys = madLibKeys(), fills = words || narrationWords();
  let out = '';
  for (let i = 0; i < src.length;) {
    const hit = keys.find(k => src.startsWith(k.key, i));
    if (!hit) { out += esc(src[i]); i++; continue; }
    const word = fills.find(w => w.key === hit.key);
    let said = word ? (word.person ? sayPerson(word.person, src.slice(i + hit.key.length), seen) : word.text) : '';
    const before = src.slice(0, i);
    if (said && /\b(a|an|the)\s+$/i.test(before)) said = said.replace(/^(a|an|the)\s+/i, ''); // "over a the bridge"
    if (said && /(^|[.!?:]\s+|\n)$/.test(before)) said = said.charAt(0).toUpperCase() + said.slice(1);
    out += said
      ? `<span class="madlib filled"><span class="madlib-fill">${esc(said)}</span><span class="madlib-label">${esc(hit.label)}</span></span>`
      : `<span class="madlib"><span class="madlib-blank"></span><span class="madlib-label">${esc(hit.label)}</span></span>`;
    i += hit.key.length;
  }
  return out;
}

// Draw the Situation card's face, then shrink any part whose filled-in names don't fit (the
// opening text, a choice's speech bubble, the Escalations), a step at a time, to 70% at most.
function drawSituation(card, situation, result = null, words = null) {
  const front = card.el.querySelector('.card-front');
  front.innerHTML = situationFront(situation, result, words);
  const back = card.el.querySelector('.card-back');
  if (back) { back.querySelectorAll('.set-tag').forEach(t => t.remove()); back.insertAdjacentHTML('beforeend', setTag(situation)); }
  const fit = (node, tooBig) => {
    for (let pct = 100; pct > 70 && tooBig(); pct -= 5) node.style.fontSize = `${pct - 5}%`;
  };
  const intro = front.querySelector('.sit-text'), introBox = front.querySelector('.sit-intro');
  if (intro && introBox) fit(intro, () => introBox.scrollHeight > introBox.clientHeight + 1);
  front.querySelectorAll('.sit-choice').forEach(c => {
    const b = c.querySelector('.sit-choice-text');
    if (b) fit(b, () => b.offsetHeight > c.clientHeight - 4);
  });
  const escs = front.querySelector('.sit-escs');
  if (escs) fit(escs, () => escs.scrollHeight > escs.clientHeight + 1);
}

function situationFront(situation, result = null, words = null) {
  const seen = new Set(); // titles on first mention, across the whole card
  const lines = situation.description.split('\n');
  const first = lines.findIndex(l => /^\s*[ABC]\)/.test(l));
  const intro = (first < 0 ? lines : lines.slice(0, first)).join('\n');
  const choices = { A: '', B: '', C: '' };
  if (first >= 0) lines.slice(first).forEach(l => {
    const m = l.match(/^\s*([ABC])\)\s*(.*)$/);
    if (m) choices[m[1]] = m[2].replace(APPROACH_AND_RISK, '');
  });
  const escalations = situation.escalations
    .map((text, i) => text && `<div class="sit-esc"><b>Escalation ${i + 1}:</b> ${madLib(text, words, seen)}</div>`)
    .join('');
  // Who won on row i (a shared win stamps every finished row).
  const winnerOn = i => result && !result.lost && (result.winners || [result]).find(w => w.row === i);
  return `
    <div class="sit-intro">
      ${result && result.lost ? '<div class="sit-lost">Lost</div>' : ''}
      <div class="sit-name">${esc(situation.name || 'Situation')}</div>
      <div class="sit-text">${madLib(intro, words, seen)}</div>
      ${SIM_RULES.riskModifier && SIM_RULES.freeApproach ? '<div class="sit-risk-head">Risk</div>' : ''}
    </div>
    <div class="sit-choices">
      ${['A', 'B', 'C'].map((k, i) => `
        <div class="sit-choice${winnerOn(i) ? ' won' : ''}">${choiceRiskHtml(situation.risks[i])}<span class="sit-choice-text">${madLib(choices[k], words, seen)}</span>${winnerOn(i) ? `<span class="sit-stamp" style="--c:${winnerOn(i).color}">★ ${esc(winnerOn(i).name)}</span>` : ''}</div>`).join('')}
    </div>
    <div class="sit-escs">${escalations}</div>${setTag(situation)}`;
}

// An initiative token has two sides: the player's place in the turn order, and OUT for a
// player who lost their next turn (a resource knocked to 0). Tap it to flip it by hand.
function initiativeFaces(n) {
  return `<span class="init-num">${n}</span><span class="init-out">OUT</span>`;
}

function setInitiative(token, n) {
  token.initiative = n;
  token.lift.querySelector('.init-num').textContent = String(n);
}

function setOut(token, out) {
  if (token.el.classList.contains('is-out') === out) return;
  token.el.classList.toggle('is-out', out);
  animateOnce(token, 'flipping', 450);
}

// Round board: pawns sit around the ring with their initiative tokens, and each
// Relationship card sits between the two players it links (W↔X between W and X).
const REL_BOARD = 720; // room for Fate-card-sized Relationships between the pawns
// The Storyteller token (SIM_RULES.obstacle), passed round the table: it sits right of the
// Storyteller's Trouble card (above their Liability), with a slot (a little above its centre,
// the token's name round the bottom) where the Obstacle die rests while it isn't on the Board.
const STORY_SIZE = 110, OBSTACLE_SIZE = DIE_SIZE, OBSTACLE_RIDE = 7;
// The token's face: a slot for the die, and its name curving round the bottom edge.
const STORY_FACE = `<span class="story-slot"></span><svg class="story-ring" viewBox="0 0 ${STORY_SIZE} ${STORY_SIZE}" aria-hidden="true">`
  + `<path id="story-arc" d="M 13 ${STORY_SIZE / 2} A ${STORY_SIZE / 2 - 13} ${STORY_SIZE / 2 - 13} 0 0 0 ${STORY_SIZE - 13} ${STORY_SIZE / 2}" fill="none"/>`
  + '<text><textPath href="#story-arc" startOffset="50%" text-anchor="middle">STORYTELLER</textPath></text></svg>';

// Relationship cards on the ring: one per pair of neighbours (just one for two players).
const relationshipCount = n => (n === 2 ? 1 : n);

const PAWN_HOME = 96, PAWN_HOME_DROP = 30; // a pawn's home disc: its size, and how far below the pawn's centre (at its base)
function relationshipBoard(x, y, players, relationships) {
  const top = y + 18;
  const ring = addStatic(el('div', 'rel-board'), x, top);
  ring.style.width = ring.style.height = `${REL_BOARD}px`;
  const cx = x + REL_BOARD / 2, cy = top + REL_BOARD / 2;
  const n = players.length;
  const R = 240;
  const at = (deg, r) => ({ x: cx + r * Math.sin(deg * Math.PI / 180), y: cy - r * Math.cos(deg * Math.PI / 180) });
  const initiative = shuffle(players.map((_, i) => i + 1));

  players.forEach((p, i) => {
    const deg = i * 360 / n;
    const pawn = at(deg, R);
    // The pawn's home: a disc in the player's colour under its base, so it's clear where it goes back.
    const home = addStatic(el('div', 'pawn-home'), pawn.x - PAWN_HOME / 2, pawn.y + PAWN_HOME_DROP - PAWN_HOME / 2);
    home.style.setProperty('--c', PLAYER_COLORS[i % PLAYER_COLORS.length]);
    const pawnPiece = createPawn({ color: PLAYER_COLORS[i % PLAYER_COLORS.length], label: p, x: pawn.x - 40, y: pawn.y - 48 });
    const tok = at(deg, R - 78);
    const initPiece = createToken({ className: 'initiative', size: 50, html: initiativeFaces(initiative[i]), x: tok.x - 25, y: tok.y - 25 });
    initPiece.initiative = initiative[i];
    initPiece.tapHandler = () => { setOut(initPiece, !initPiece.el.classList.contains('is-out')); return true; };
    TABLE.players[i] = {
      letter: p, index: i, color: PLAYER_COLORS[i % PLAYER_COLORS.length],
      pawn: pawnPiece, pawnHome: { x: pawnPiece.x, y: pawnPiece.y }, initToken: initPiece,
    };

    // One Relationship between each pair of neighbours. Two players are each other's only
    // neighbour, so they share a single card, upright in the middle of the ring.
    if (i >= relationshipCount(n)) return;
    const cardDeg = deg + 180 / n;
    const pos = n === 2 ? { x: cx, y: cy } : at(cardDeg, R);
    // Tilt each card along the ring, but never more than sideways so it stays readable.
    let rot = n === 2 ? 0 : ((cardDeg + 180) % 360) - 180;
    if (rot > 90) rot -= 180;
    if (rot < -90) rot += 180;
    const zx = pos.x - PC_CARD.w / 2, zy = pos.y - PC_CARD.h / 2;
    const zone = addZone({
      accepts: 'relationship', x: zx, y: zy, w: PC_CARD.w, h: PC_CARD.h, rot,
      el: zoneOutline(zx, zy, PC_CARD.w, PC_CARD.h, 'Relationship', rot),
    });
    TABLE.relZones[i] = zone; // links player i and player i + 1
    if (relationships) snapTo(placePcCard(drawEven(relationships), zx, zy), zone, false);
  });
}

// ---- Read-aloud situation ----
// The Situation text with its symbols swapped for the words on the dealt cards:
// 👿 / 😇 → the Villain's / Ally's name, 🏠 → the Location, 🛠️ → the MacGuffin,
// a location feature (🌉) → that feature, and an element + attribute pair (😇🚩) →
// that attribute (the Ally's goal). Approach and risk icons are left as they are.
// It reads whatever is on the table now, so turning or swapping a name card updates it.

let narration = null; // { el, situation }

const lowerFirst = t => t.charAt(0).toLowerCase() + t.slice(1);
const withArticle = t => (/^(a|an|the)\s/i.test(t) ? lowerFirst(t) : `the ${lowerFirst(t)}`);
const noEllipsis = t => t.replace(/\.\.\.|…/g, '').trim();
const noVS = t => t.replace(/️/g, ''); // emoji variation selectors vary between sources

// The name showing on the face-down card(s) tucked under a card, left to right: an Ally or
// Villain has two, a first name (Concept) and a last name (Trouble).
function shownTuckedName(piece) {
  return piece.children.filter(c => !c.faceUp && c.card && c.card.names)
    .sort((a, b) => a.x - b.x)
    .map(t => noEllipsis(t.card.names[t.rot === 180 ? 1 : 0]))
    .join(' ');
}

// Each entry maps a symbol (or symbol pair) to words. People (Villain, Ally) get their
// name and title: "Vex, the Scheming Baron" the first time, then just "Vex".
function narrationWords() {
  const words = [];
  for (const kind of ['villain', 'ally', 'macguffin', 'location']) {
    const piece = pieces.find(p => p.cardKind === kind && !p.parent);
    if (!piece) continue;
    const { card } = piece;
    const [head, ...lineIcons] = card.icons.map(noVS);
    const name = shownTuckedName(piece);

    lineIcons.forEach((icon, i) => {
      const text = card.lines[i] && card.lines[i].text;
      if (!text) return;
      words.push({ key: head + icon, text: lowerFirst(text) });
      if (kind === 'location') words.push({ key: icon, text: withArticle(text) });
    });

    const bare = card.name.replace(/^the\s+/i, ''); // "The Miracle Child": the text adds its own "the"
    if (kind === 'villain' || kind === 'ally') {
      words.push({ key: head, person: { id: kind, name, title: `the ${card.name.replace(/^the\s+/i, '')}` } });
    } else if (kind === 'macguffin') {
      words.push({ key: head, text: `the ${name ? `${lowerFirst(name)} ` : ''}${bare.toLowerCase()}` });
    } else {
      const place = `the ${name ? `${name} ` : ''}${bare}`;
      words.push({ key: head, text: place });
      words.push({ key: '🏠', text: place }); // situations use 🏠 for any location
    }
  }
  return words.sort((a, b) => b.key.length - a.key.length); // longest (pairs) first
}

function sayPerson({ id, name, title }, after, seen) {
  const first = !seen.has(id);
  seen.add(id);
  if (!name) return title;
  if (!first) return name;
  if (/^['’]s\b/.test(after)) return `${title} ${name}`;            // "the Grand Admiral Mira's fleet"
  return `${name}, ${title}${/^\s+[A-Za-z]/.test(after) ? ',' : ''}`;    // "Mira, the Grand Admiral, is"
}

function narrate(text, words, seen) {
  const src = noVS(text);
  let out = '';
  for (let i = 0; i < src.length;) {
    const hit = words.find(w => src.startsWith(w.key, i));
    if (!hit) { out += esc(src[i]); i++; continue; }
    const before = src.slice(0, i), after = src.slice(i + hit.key.length);
    let said = hit.person ? sayPerson(hit.person, after, seen) : hit.text;
    if (/\b(a|an|the)\s+$/i.test(before)) said = said.replace(/^(a|an|the)\s+/i, ''); // "over a the bridge"
    if (/(^|[.!?:]\s+|\n|[A-C]\)\s*)$/.test(before)) said = said.charAt(0).toUpperCase() + said.slice(1);
    out += `<b>${esc(said)}</b>`;
    i += hit.key.length;
  }
  return out;
}

// ---- The Scene die ----
// Each Situation is built around one Element line, its `key` (a location feature like 🌉, or
// a pair like 😇🔒), named in its description. That line's approach goes on the Scene die, at
// the left of the Board's banner. For the whole situation, on every row, any character whose
// Concept or Asset shows that approach gets +1: the scene suits certain characters. So the
// same Situation plays differently with a different Location, Villain, Ally or MacGuffin.

const ELEMENT_KINDS = ['villain', 'ally', 'macguffin', 'location'];

function sceneKey(situation) {
  if (!situation || !SIM_RULES.sceneModifier) return null;
  const key = situation.key && noVS(situation.key);
  const text = noVS(situation.description);
  let fallback = null;
  for (const kind of ELEMENT_KINDS) {
    const piece = pieces.find(p => p.cardKind === kind && !p.parent);
    if (!piece) continue;
    const [head, ...lineIcons] = piece.card.icons;
    for (let i = 0; i < lineIcons.length; i++) {
      const line = piece.card.lines[i];
      if (!line) continue;
      const keys = [noVS(head) + noVS(lineIcons[i])];
      if (kind === 'location') keys.push(noVS(lineIcons[i])); // location features appear on their own
      const found = { icon: lineIcons[i], text: line.text, approach: line.approach, from: piece.card.name };
      if (key && keys.includes(key)) return found;
      if (!key && !fallback && keys.some(k => text.includes(k))) fallback = found; // no key given: first line named
    }
  }
  return fallback;
}

// Put the Scene die on the Board (left end of the banner) and mark the characters it favours.
function updateSceneBoard(scene = undefined) {
  if (!TABLE || !TABLE.situation) return;
  const key = scene === undefined ? sceneKey(TABLE.situation) : scene;
  if (scene === undefined) TABLE.scene = key;
  const card = TABLE.situationCard;
  if (key) {
    const value = APPROACHES.findIndex(a => noVS(a) === noVS(key.approach)) + 1;
    if (!TABLE.sceneDie || !TABLE.sceneDie.el.isConnected) {
      TABLE.sceneDie = createDie({ className: 'die-scene', faces: APPROACHES, size: DIE_SIZE, value, x: TABLE.sceneDieAt.x, y: TABLE.sceneDieAt.y });
    } else {
      setDieValue(TABLE.sceneDie, value);
    }
  } else if (TABLE.sceneDie && TABLE.sceneDie.el.isConnected) {
    removePiece(TABLE.sceneDie);
    TABLE.sceneDie = null;
  }
  if (TABLE.sceneNoteEl) {
    TABLE.sceneNoteEl.innerHTML = key ? `<span class="mat-scene-what">${key.icon} ${esc(lowerFirst(key.text))}</span> <em>${sceneMod()} ${SIM_RULES.sceneBy === 'approach' ? (SIM_RULES.sceneClaim ? `to the first going in ${key.approach} each round` : `going in with ${key.approach}`) : `for ${key.approach} characters`}</em>` : '';
  }
  TABLE.players.forEach(pl => {
    if (!pl.badgeEl) return;
    const fits = key && sceneFits(pl, key);
    pl.badgeEl.classList.toggle('scene-boost', !!fits);
    pl.badgeEl.dataset.scene = fits ? sceneMod() : '';
  });
}

// Does this character's Concept or Asset show the Scene die's approach?
function sceneFits(pl, key) {
  if (!key || !pl.zones || SIM_RULES.sceneBy === 'approach') return false; // (it's about the roll then, not the character)
  return ['concept', 'boon'].some(slot => {
    const card = pl.zones[slot].occupant && pl.zones[slot].occupant.card;
    return card && (card.approaches || []).some(a => noVS(a) === noVS(key.approach));
  });
}

// "+1" or "−1", as shown on the Board and in the read-aloud panel.
function sceneMod() {
  const m = SIM_RULES.sceneModifier;
  return m > 0 ? `+${m}` : `\u2212${-m}`;
}

function sceneLine(key) {
  if (!key) return '';
  return `<p class="narr-scene"><span>Scene:</span> ${key.icon} ${esc(lowerFirst(key.text))}: <b>${sceneMod()}</b> ${SIM_RULES.sceneBy === 'approach' ? `on any roll going in with ${key.approach}` : `on any row for a character whose Concept or Asset shows ${key.approach}`}.</p>`;
}

function renderNarration() {
  if (!narration || !narration.el.isConnected) {
    // No read-aloud panel: still keep the Scene die in step with the table (e.g. a Location
    // swapped by hand), unless a past act is being re-enacted.
    const live = !TABLE || !TABLE.history || !TABLE.history.length || TABLE.shownAct === TABLE.history.length - 1;
    if (live) updateSceneBoard();
    return;
  }
  const { el: node, situation } = narration;
  const words = narration.words || narrationWords(); // a past act keeps the words it was played with
  const seen = new Set(); // shared so titles are only given on first mention
  const description = narrate(situation.description, words, seen);
  const escalations = situation.escalations
    .map((text, i) => text && `<p class="narr-esc"><span>Escalation ${i + 1}:</span> ${narrate(text, words, seen)}</p>`)
    .join('');
  const r = narration.result;
  const ending = !r ? '' : r.lost
    ? '<p class="narr-result">The heroes lost this one.</p>'
    : `<p class="narr-result">★ <b style="color:${r.color}">${esc(r.name)}</b> did it: <i>${r.action}</i>.</p>`;
  // The live scene, or the one a past act was played with when re-enacting it.
  if (!narration.words) updateSceneBoard();
  const scene = sceneLine(narration.words ? narration.scene : TABLE && TABLE.scene);
  node.querySelector('.narr-body').innerHTML = `<p>${description}</p>${scene}${escalations}${ending}`;
}

function narrationPanel(x, y, w, situation) {
  const node = el('div', 'narration', `
    <div class="narr-head">
      <span class="narr-title">${esc(situation.name || 'Situation')}</span>
      <button type="button" class="narr-speak" aria-label="Read aloud">🔊</button>
    </div>
    <div class="narr-body"></div>`);
  node.style.width = `${w}px`;
  addStatic(node, x, y);
  narration = { el: node, situation };
  renderNarration();

  node.querySelector('.narr-speak').addEventListener('click', () => {
    if (!('speechSynthesis' in window)) return;
    if (speechSynthesis.speaking) { speechSynthesis.cancel(); return; }
    const spoken = node.querySelector('.narr-body').innerText.replace(/\p{Extended_Pictographic}|[➕➖]/gu, ' ');
    speechSynthesis.speak(new SpeechSynthesisUtterance(spoken));
  });
  return node;
}

// The Situation card's filled-in blanks follow the table too (a Location swapped, a name card
// turned), unless a past act is on show: that one keeps the words it was played with.
function refreshSituationCard() {
  const card = TABLE && TABLE.situationCard;
  if (!card || !card.el.isConnected) return;
  const n = (TABLE.history || []).length;
  const entry = n ? TABLE.history[TABLE.shownAct ?? n - 1] : null;
  if (entry && entry.words) return;
  drawSituation(card, entry ? entry.situation : TABLE.situation, entry ? entry.result : null);
}

// Called by the table after any drop, flip or turn.
window.onTableChange = () => { renderNarration(); refreshSituationCard(); updateBuild(); };

// ---- New game: building the characters ----
// While TABLE.building, each character's resource dice follow the Concept and Trouble in their
// slots, and Start game stays greyed out until every character has a Concept, a Trouble and an
// Asset, a first and a last name, and a portrait, and every Relationship on the wheel is placed.
function buildMissing() {
  const missing = [];
  TABLE.players.forEach(pl => {
    const z = pl.zones;
    if (!z) return;
    const need = [
      [z.concept.occupant, 'Concept'], [z.trouble.occupant, 'Trouble'], [z.boon.occupant, 'Asset'],
      [z.concept.nameZone.occupant, 'first name'], [z.trouble.nameZone.occupant, 'last name'], [z.portrait.occupant, 'portrait'],
    ].filter(([have]) => !have).map(([, what]) => what);
    if (need.length) missing.push(`${pl.letter}: ${need.join(', ')}`);
  });
  const rels = TABLE.relZones.filter(z => !z.occupant).length;
  if (rels) missing.push(`${rels} Relationship${rels > 1 ? 's' : ''} on the wheel`);
  return missing;
}

function updateBuild() {
  const btn = document.getElementById('start-game-btn');
  if (!btn) return;
  btn.hidden = !(TABLE && TABLE.building);
  if (btn.hidden) return;
  TABLE.players.forEach(pl => {
    if (!pl.zones || !pl.dice) return;
    const concept = pl.zones.concept.occupant, trouble = pl.zones.trouble.occupant;
    Object.entries(pl.dice).forEach(([res, die]) => {
      const value = (SIM_RULES.resourceStart ?? RESOURCE_START) + (concept?.card.resource === res) - (trouble?.card.resource === res);
      if (die.value !== value) setDieValue(die, Math.max(1, Math.min(6, value)));
    });
  });
  // A portrait slides under the name cards and the board, as when dealt.
  (TABLE.pool || []).filter(p => p.cardKind === 'relationship')
    .forEach(p => p.el.classList.toggle('tucked-name', TABLE.players.some(pl => pl.zones && pl.zones.portrait === p.zone)));
  const missing = buildMissing();
  btn.disabled = missing.length > 0;
  btn.title = missing.length ? `Still to do — ${missing.join(' · ')}` : 'Everyone’s ready: start the game';
}

// ---- Spotlight tokens ----
// Each player's scoring tokens: their colour, a stage spotlight shining down on their letter.
// Players bet them onto the Successes column; beaten situations score them.

const SPOTLIGHT_TOKENS = 20; // per player (with takeSpotlight: in the shared pool, per player)
const SPOTLIGHT_SIZE = 62;
const SPOTLIGHT_STEP = 2.5; // stacking offset in a player's single spotlight stack

// A stage spotlight on its bracket, top left, throwing a beam down to a pool of light (where
// the owner's letter goes, if any). Drawn on the token's colour (--tok).
function spotlightArt(letter) {
  // The lamp is tilted so its lens faces down and to the right, straight along the beam.
  return `<svg viewBox="0 0 100 100" aria-hidden="true">
    <polygon points="35,56 59,34 86,78 42,81" fill="rgba(255,246,200,.8)"/>
    <ellipse cx="64" cy="79" rx="22" ry="7.5" fill="#fff"/>
    <rect x="25" y="13" width="22" height="4" rx="2" fill="#2b2b2b"/>
    <rect x="34.5" y="16" width="3" height="8" fill="#2b2b2b"/>
    <g transform="rotate(-42 37 34)">
      <path d="M25 26 Q37 18 49 26" fill="none" stroke="#2b2b2b" stroke-width="3.2"/>
      <rect x="25" y="25" width="24" height="16" rx="3" fill="#2b2b2b"/>
      <polygon points="25,41 49,41 53,49 21,49" fill="#454545"/>
      <ellipse cx="37" cy="46" rx="10" ry="3.6" fill="#fff"/>
    </g>
    <text x="64" y="83.5" text-anchor="middle" font-size="14" font-weight="900" fill="#1a1a1a">${esc(letter)}</text>
  </svg>`;
}

// Edge: a shared pile of +1 tokens. A player who fails takes one; spending one adds +1
// to a roll.
const EDGE_TOKENS = 36; // enough for 3 players' act bonuses (2+3+5 each) plus failures
const EDGE_SIZE = 50;
// Story Points and Scored spotlight, beside the Trouble card: tokens per stack (two stacks side by side).
const STORY_STACK = 8, SCORE_STACK = 12;
const EDGE_STEP = 1.5; // stacking offset, so the full pile stays clear of the Fate deck

function edgeArt() {
  return '<div class="edge-face"><b>+1</b><small>Story</small></div>';
}

function placeEdgeSupply(x, y) {
  const tokens = [];
  for (let i = 0; i < EDGE_TOKENS; i++) {
    const t = createToken({ className: 'edge', size: EDGE_SIZE, html: edgeArt(), x, y: y - i * EDGE_STEP });
    t.home = { x: t.x, y: t.y };
    tokens.push(t);
  }
  return { supply: tokens, home: { x, y } };
}

// A player's tokens in one neat stack, its bottom token at (x, y).
function placeSpotlightTokens(letter, color, x, y) {
  const tokens = [];
  for (let i = 0; i < SPOTLIGHT_TOKENS; i++) {
    const t = createToken({
      className: 'spotlight',
      size: SPOTLIGHT_SIZE,
      html: spotlightArt(letter),
      x,
      y: y - i * SPOTLIGHT_STEP,
    });
    t.el.style.setProperty('--tok', color);
    t.player = letter;
    tokens.push(t);
  }
  return tokens;
}

// ---- Taking spotlight (SIM_RULES.takeSpotlight) ----
// Neutral spotlight tokens: a shared pool beside the Fate deck, a stack in each row's
// Successes box, and a "This scene" spot in front of each player for tokens they've taken.
const POOL_COLOR = '#ffc845'; // spotlight yellow
const POOL_COLUMN = 27; // tokens per column in the pool (up to three columns, under the Fate deck)
function poolSpot(k) {
  return { x: TABLE.poolAt.x + Math.floor(k / POOL_COLUMN) * (SPOTLIGHT_SIZE + 10), y: TABLE.poolAt.y - (k % POOL_COLUMN) * SPOTLIGHT_STEP };
}
function returnToPool(token) {
  token.el.classList.remove('staked');
  token.player = null;
  token.help = false;
  token.el.classList.remove('help-token');
  const s = poolSpot(TABLE.pool.length);
  glide(token, s.x, s.y);
  TABLE.pool.push(token);
}
// A row's stack, fanned out so the tokens left can be counted.
function successSpot(rowIndex, k, n) {
  const c = TABLE.cell(rowIndex, matCol('successes'));
  return { x: c.x - SPOTLIGHT_SIZE / 2 + (k - (n - 1) / 2) * 18, y: c.y - SPOTLIGHT_SIZE / 2 };
}
// A new situation: whatever is left on the rows goes back to the pool, then each row gets a
// fresh stack of `target` tokens.
function fillSuccessStacks(target) {
  TABLE.rows.forEach((row, i) => {
    (row.stack || []).forEach(returnToPool);
    row.stack = [];
    for (let k = 0; k < target; k++) {
      const t = TABLE.pool.pop();
      if (!t) break;
      const s = successSpot(i, k, target);
      glide(t, s.x, s.y);
      row.stack.push(t);
    }
  });
}
function clearSuccessStacks() {
  TABLE.rows.forEach(row => { (row.stack || []).forEach(returnToPool); row.stack = []; });
}

// ---- A new Location each act ----
// The Location on the table and the card tucked under it (its place word) go back to
// the deck. A different Location is drawn, with a place word from one of the others.
function drawNewLocation() {
  const old = pieces.find(p => p.cardKind === 'location' && !p.parent);
  const oldCards = old ? [old.card, ...old.children.map(c => c.card)] : [];
  if (old) removePiece(old);
  let choices = shuffle(TABLE.locationCards.filter(c => c !== oldCards[0]));
  // Spread the acts' Locations over the sets in play: only the sets that have shown one least so far.
  TABLE.locationUses = TABLE.locationUses || {};
  if (oldCards[0]) TABLE.locationUses[oldCards[0].set] = (TABLE.locationUses[oldCards[0].set] || 0) + 1;
  const uses = c => TABLE.locationUses[c.set] || 0, fewest = Math.min(...choices.map(uses));
  choices = choices.filter(c => uses(c) === fewest);
  const card = choices.pop();
  const main = placeElementCard(card, TABLE.locationSlot.x, TABLE.locationSlot.y);
  // Prefer a place word that wasn't just showing.
  const nameDeck = shuffle(TABLE.locationCards.filter(c => c !== card));
  nameDeck.sort((a, b) => (oldCards.includes(a) ? 0 : 1) - (oldCards.includes(b) ? 0 : 1)); // drawn from the end
  const tucked = tuckNameCard(main, nameDeck, placeElementCard);
  [main, tucked].forEach(piece => animateOnce(piece, 'dealing', 1000));
  return main;
}

// ---- Act history ----
// Each act played adds a button next to the Situation title. Tapping one puts that act's
// card (with its winner stamp) back on the table and in the read-aloud panel.

function showAct(i) {
  const entry = TABLE.history[i];
  if (!entry) return;
  TABLE.shownAct = i;
  const card = TABLE.situationCard;
  drawSituation(card, entry.situation, entry.result, entry.words || null);
  setFaceUp(card, true);
  pulse(card);
  if (narration) {
    narration.situation = entry.situation;
    narration.result = entry.result;
    narration.words = entry.words || null;
    narration.scene = entry.scene || null;
    narration.el.querySelector('.narr-title').textContent = entry.situation.name || 'Situation';
    renderNarration();
  }
  if (entry.scene !== undefined) updateSceneBoard(entry.scene); // its Scene die, as played
  renderActTabs();
}

function renderActTabs() {
  const tabs = TABLE.actTabs;
  if (!tabs) return;
  tabs.innerHTML = '';
  TABLE.history.forEach((entry, i) => {
    const btn = el('button', `act-tab${i === TABLE.shownAct ? ' active' : ''}${entry.result ? (entry.result.lost ? ' lost' : ' won') : ''}`, esc(entry.label || entry.act));
    btn.type = 'button';
    btn.addEventListener('click', () => showAct(i));
    tabs.appendChild(btn);
  });
}

// ---------------------------------------------------------------------------
// Deal
// ---------------------------------------------------------------------------

// Handles to the pieces and slots on the table, rebuilt by every deal. The gameplay
// simulator (sim.js) uses these to move things around.
let TABLE = null;

// mode 'deal': everything dealt, ready to play.
// mode 'new':  clean slate for building characters: empty slots, plus a pool of
//              8 Concepts, 8 Troubles, 8 Assets and 4 Relationships to choose from.
function deal(mode = 'deal') {
  const fresh = mode === 'new';
  clearWorld();
  shownNames.clear();
  TABLE = { players: [], relZones: [], rows: [{}, {}, {}], building: fresh };

  const players = DATA.players.slice(0, PLAYER_COUNT); // W, X, Y, Z: as many as are playing
  const concepts = buildFromSets(d => buildPcDeck('concept', d.concepts, d.firstNames, '✔️', SIM_RULES.charApproaches || 2, true));
  const troubles = buildFromSets(d => buildPcDeck('trouble', d.troubles, d.lastNames, '✖️', SIM_RULES.charApproaches || 2, true));
  const boons = buildBoonDeck();
  // Each Relationship's back shows a portrait in the style of its own set (portraits.js).
  const relationships = buildFromSets((d, key) => {
    const portraits = makePortraits(d.relationships.length, key);
    return d.relationships.map((text, i) => ({ kind: 'relationship', text, sign: '', approaches: pickApproaches(2), portrait: portraits[i] }));
  });
  const macguffins = buildFromSets(d => buildElementDeck('macguffin', 'Object', d.macguffins)); // the MacGuffin, called an Object on the card
  const allies = buildFromSets(d => buildElementDeck('ally', 'Ally', d.allies));
  const villains = buildFromSets(d => buildElementDeck('villain', 'Villain', d.villains));
  const locations = buildFromSets(d => buildElementDeck('location', 'Location', d.locations, d.placeAdjectives));
  TABLE.locationCards = [...locations]; // the whole Location deck, for drawing a new one each act
  const situation = DATA.situations[randInt(DATA.situations.length)];

  // ---- Layout: two columns, so the table fits beside the simulator panel ----
  // Left: Situation card | Board | Fate + Edge across the top, the characters underneath.
  // Right: the Relationship wheel, with the four Elements 2 x 2 below it.
  const TOP = 30; // the Board's and the Situation card's top
  // The Assets sit just off the player board's left edge, beside ➕ strips, and the Liabilities off
  // its right edge, beside ➖ strips (under the Story Points and Scored spotlight). Signs: ✔️ Concept,
  // ✖️ Trouble, ➕ Asset, ➖ Liability (swapped 2026-10-20).
  const BOARD_EDGE = 0; // the board's margin round the sheet (the side strips frame it)
  const BOARD_SIDE = 46; // a strip down each side of the board marking the Asset / Liability places
  const BOARD_W = SHEET_W + 2 * BOARD_EDGE + 2 * BOARD_SIDE;
  const BLOCK_W = PC_CARD.w + BOARD_W + PC_CARD.w + 30; // Asset | board | Liability | gap
  // Two rows. Top, left to right: the Elements (Location and Object on top, the Ally and Villain
  // under the Location, the Fate deck and the spotlight pool under the Object), the Situation
  // card and Board (the focus, in the middle), and the Relationship wheel. Bottom: the characters.
  const LEFT = 40;
  const LOC = elSize('location');
  const PEOPLE_W = 2 * EL_CARD.w + EL_GAP;             // the Ally and Villain side by side
  const OBJ_X = LEFT + Math.max(LOC.w, PEOPLE_W) + EL_GAP; // the Object's column
  const EL_R = OBJ_X + EL_CARD.w;                       // the Elements' right edge
  const SIT_X = EL_R + 50;
  const BOARD_X = SIT_X + SIT_CARD.w; // the Board, flush against the Situation card's right edge
  const RX = BOARD_X + MAT_W + 50;    // the Relationship wheel, right of the Board
  const TOP_R = RX + REL_BOARD;       // the top row's right edge
  // The characters sit in a single row under it all (CHAR_COLS = 2 would make rows of two).
  const CHAR_COLS = players.length;
  const CHAR_ROW_H = 980; // one row of characters: spotlight stack and badge down to the Edge row
  relationshipBoard(RX, 12, players, fresh ? null : relationships);
  narration = null; // no read-aloud panel: the simulator panel tells the story

  const ELY = 30; // the top of the first card's name card
  // Name cards tucked above each element (none on the Object): a person's
  // first and last name from a spare Concept and Trouble side by side (like the characters'),
  // and a place adjective from a spare Location.
  const elementSlots = [
    [macguffins, []],
    [allies, [[concepts, placePcCard], [troubles, placePcCard]]],
    [villains, [[concepts, placePcCard], [troubles, placePcCard]]],
    [locations, [[locations, placeElementCard]]],
  ];
  // Each card's top-left corner (its name card peeks out above it).
  const LOC_Y = ELY + PEEK;
  const PEOPLE_Y = LOC_Y + LOC.h + EL_GAP + PEEK;
  const OBJECT_Y = PEOPLE_Y; // the Object, right of the Villain (the Fate deck is above it)
  const elementAt = deck => (deck === locations ? [LEFT, LOC_Y]
    : deck === allies ? [LEFT, PEOPLE_Y]
    : deck === villains ? [LEFT + EL_CARD.w + EL_GAP, PEOPLE_Y]
    : [OBJ_X, OBJECT_Y]);
  // The Location, Villain, Ally and Object share the sets in play out evenly: the sets in a random
  // order, handed round the four kinds (also random), e.g. Object and Ally from one, Location and
  // Villain from the other.
  const setTurns = shuffle(DATA.sets.map(s => s.set));
  const setFor = new Map(shuffle(elementSlots.map(([deck]) => deck)).map((deck, i) => [deck, setTurns[i % setTurns.length]]));
  elementSlots.forEach(([deck, namers]) => {
    const main = placeElementCard(drawFromSet(deck, setFor.get(deck)), ...elementAt(deck));
    if (deck === locations) TABLE.locationSlot = { x: main.x, y: main.y };
    // One name card is centred above the element card; two sit side by side.
    const tucked = namers.map(([nameDeck, placeName]) => tuckNameCard(main, nameDeck, placeName));
    const GAP = 4;
    const rowW = tucked.reduce((sum, t) => sum + t.w, 0) + GAP * (tucked.length - 1);
    let x = (main.w - rowW) / 2;
    tucked.forEach(t => { moveBy(t, x, 0); x += t.w + GAP; });
  });

  // ---- Situation card | A/B/C board ----
  const ROW2 = TOP;
  // "Situation" title, with a button per act as the game goes on (see showAct).
  // The Situation card sits so its three choices (each a Board row tall, under the description)
  // line up with the Board's rows.
  const SIT_Y = ROW2 + MAT_TOP - SIT_CARD.border - SIT_CARD.intro;
  // "Situation" above the card's top left corner; the act tabs under its bottom left corner,
  // kept left of the Board (they wrap).
  TABLE.actTabs = addStatic(el('div', 'act-tabs'), SIT_X, SIT_Y + SIT_CARD.h + 12);
  TABLE.actTabs.style.width = `${SIT_CARD.w}px`;
  TABLE.history = [];
  TABLE.situation = situation;
  TABLE.situationCard = createCard({
    className: 'situation-card',
    w: SIT_CARD.w, h: SIT_CARD.h, x: SIT_X, y: SIT_Y,
    front: situationFront(situation),
    back: plainBack('Situation'),
  });
  drawSituation(TABLE.situationCard, situation); // again, now it's on the table, so it can be fitted

  const cell = buildMat(BOARD_X, ROW2, situation);
  TABLE.sceneDieAt = { x: BOARD_X + MAT_PAD + 8, y: ROW2 + MAT_PAD + (MAT_BANNER - DIE_SIZE) / 2 + 8 }; // left end of the banner
  // "Edge" over the Edge die's home spot.
  const edgeName = addStatic(el('div', 'edge-die-name', 'Edge'), TABLE.sceneDieAt.x, TABLE.sceneDieAt.y - 22);
  edgeName.style.width = `${DIE_SIZE}px`;
  TABLE.sceneNoteEl = document.querySelector('.mat .mat-scene');
  TABLE.cell = cell;
  TABLE.boardAt = { x: BOARD_X, y: ROW2 }; // the Board's top left corner (for lighting up a row)
  const boardBottom = ROW2 + MAT_TOP + MAT_ROW * 3 + MAT_FOOT + MAT_PAD;
  TABLE.lostAt = { x: BOARD_X + 130, y: boardBottom + 12 };
  // Where a resolved roll's cards are shown: a line centred under the Board, overlapping its bottom edge.
  TABLE.showcaseAt = { x: BOARD_X + MAT_W / 2, y: boardBottom - 70 };
  if (SIM_RULES.maxStake) { // only with stakes on
    countedLabel('Lost stakes', BOARD_X, boardBottom + 30, 'pair-label', 'spotlight',
      { x: TABLE.lostAt.x - 20, y: TABLE.lostAt.y - 40, w: 420, h: SPOTLIGHT_SIZE + 60 });
  }
  TABLE.lost = [];
  // Where Minus dice sit. With the Clear seat, the Minus box covers rows A-B (a third die only
  // appears for a moment, while someone holds the line) and the Clear box is row C.
  const seatRule = SIM_RULES.clearTiming === 'end';
  TABLE.minusAt = (k, size) => {
    const c = cell(seatRule ? 0 : 1, matCol('minus'));
    const dy = seatRule ? ([-8, 66][k] ?? 29) : (k === 0 ? -60 : 60);
    return { x: c.x - size / 2 + (k >= 2 ? 16 : 0), y: c.y - size / 2 + dy };
  };
  const seat = cell(2, matCol('minus'));
  TABLE.clearSeat = { x: seat.x, y: seat.y - 6 };
  if (!SIM_RULES.freeApproach) situation.approaches.forEach((appr, row) => {
    const idx = APPROACHES.indexOf(appr);
    if (idx < 0) return;
    const c = cell(row, matCol('approach'));
    TABLE.rows[row].approachDie = createDie({ className: 'die-approach', size: DIE_SIZE, faces: APPROACHES, value: idx + 1, x: c.x - DIE_SIZE / 2, y: c.y - DIE_SIZE / 2 });
  });


  updateSceneBoard();
  renderNarration();

  // ---- Fate deck: draw pile and discard side by side, right of the Location (above the Object) ----
  const FX = OBJ_X, FY = ELY;
  const drawZone = addZone({
    accepts: 'fate', faceDown: true, x: FX, y: FY, w: FATE_CARD.w, h: FATE_CARD.h,
    el: zoneOutline(FX, FY, FATE_CARD.w, FATE_CARD.h, 'Draw'),
  });
  const discardX = FX + EL_CARD.w - FATE_CARD.w;
  const discardZone = addZone({
    accepts: 'fate', x: discardX, y: FY, w: FATE_CARD.w, h: FATE_CARD.h,
    el: zoneOutline(discardX, FY, FATE_CARD.w, FATE_CARD.h, 'Discard'),
  });
  buildFateDeck().forEach(card => {
    const piece = createCard({
      className: 'fate-card', w: FATE_CARD.w, h: FATE_CARD.h, x: FX, y: FY, faceUp: false,
      front: fateFront(card), back: plainBack('Fate'),
    });
    piece.cardKind = 'fate';
    piece.fate = card;
    snapTo(piece, drawZone, false);
  });
  TABLE.fate = { drawZone, discardZone };

  // Edge supply: in the centre of the Relationship wheel (with two players their shared
  // Relationship card is there, so the pile sits just left of it).
  const ringX = RX + REL_BOARD / 2 - (players.length === 2 ? 150 : 0), ringY = 12 + 18 + REL_BOARD / 2;
  TABLE.edge = placeEdgeSupply(ringX - EDGE_SIZE / 2, ringY);
  countedLabel('Story Points', ringX - 36, ringY + EDGE_SIZE + 4, 'pair-label edge-label', 'edge', {
    x: TABLE.edge.home.x - 20, y: TABLE.edge.home.y - EDGE_TOKENS * EDGE_STEP - 20,
    w: EDGE_SIZE + 40, h: EDGE_TOKENS * EDGE_STEP + EDGE_SIZE + 40,
  });

  // The Liability deck isn't on the table (assume it's nearby): a Liability card only appears when a
  // player draws one, at random, and leaves the table when it goes back in the deck.
  TABLE.bane = { deck: shuffle((DATA.banes || []).map(b => ({ kind: 'bane', text: b.text, sign: '➖', approaches: b.approaches, set: b.set }))) };

  // ---- Bottom row: the characters ----
  // Under the whole top row: the Elements, the
  // Situation card's act tabs (up to two lines of them) and the wheel. A player's badge sits 42
  // above PC_TOP, the Storyteller token above that.
  const topBottom = Math.max(PEOPLE_Y + EL_CARD.h + 10, SIT_Y + SIT_CARD.h + 12 + 90, 12 + 18 + REL_BOARD);
  const PC_TOP = Math.ceil(topBottom + 26 + 175); // room for each player's portrait and counters above their area
  // Where each player's area starts: four fill the top row's width, edge to edge, evenly
  // spaced; two or three are centred under it with equal space between and around them.
  const AREA_W = BLOCK_W - 30, ROW_W = TOP_R - LEFT, n = players.length;
  const gap = n >= 4 ? Math.max(30, (ROW_W - n * AREA_W) / (n - 1)) : Math.max(30, (ROW_W - n * AREA_W) / (n + 1));
  const rowStart = n >= 4 ? LEFT : LEFT + Math.max(0, (ROW_W - n * AREA_W - (n - 1) * gap) / 2);
  const blockX = i => Math.round(rowStart + i * (AREA_W + gap));
  const CHARS_R = blockX(n - 1) + AREA_W;

  // The cards beside the board can reach lower than the sheet.
  let charBottom = 0; // the lowest point of any player area
  players.forEach((p, i) => {
    const bx = blockX(i % CHAR_COLS);
    const rowTop = PC_TOP + Math.floor(i / CHAR_COLS) * CHAR_ROW_H; // this player's row of the grid
    const sheetX = bx + PC_CARD.w + BOARD_SIDE + BOARD_EDGE;
    const sheetY = rowTop + PEEK + PC_CARD.h; // the dice right under the Concept and Trouble

    // The player board, behind the Concept and Trouble (their places are marked on it) and the
    // sheet: the Asset slots sit just off its left edge and the Liability slots off its right edge.
    const boardX = bx + PC_CARD.w, boardY = rowTop + PEEK - 10; // the Asset touches its left edge
    const boardR = boardX + BOARD_W;                    // the Liability touches its right edge
    const boonTop = rowTop + PEEK; // Asset 1 left of the Concept, Liability 1 right of the Trouble
    const playerBoard = addStatic(el('div', 'player-board'), boardX, boardY);
    playerBoard.style.width = `${BOARD_W}px`;
    playerBoard.style.height = `${sheetY + SHEET_H + 10 - boardY}px`; // from the Concept's top to the sheet's foot
    // The Asset and Liability places, no rules text: a strip down each side of the board, level with
    // each card (Asset 1 and 2 on the left, Liability 1 and 2 on the right), open towards the card.
    const sideSlot = (x, y, open, sign, name) => {
      const node = addStatic(el('div', `side-slot open-${open}`, `<span class="side-sign">${sign}</span><span class="side-name">${name}</span>`), x, y + 6);
      node.style.width = `${BOARD_SIDE - 6}px`;
      node.style.height = `${PC_CARD.h - 12}px`;
    };
    [0, 1].forEach(k => {
      sideSlot(boardX, boonTop + k * STACK_STEP, 'left', '➕', `Asset ${k + 1}`);
      sideSlot(boardR - BOARD_SIDE + 6, boonTop + k * STACK_STEP, 'right', '➖', `Liability ${k + 1}`);
    });

    // Portrait: a Relationship card turned portrait-side up, centred above the board with its
    // "Relationship" strip tucked under the name cards and the board, so just the square picture
    // shows (the player's approach die on its corner). Story Points to its left, Scored spotlight to
    // its right; the badge and This scene stack above Asset 1, the Storyteller token above Liability 1.
    const portraitX = boardX + (BOARD_W - PC_CARD.w) / 2;
    const portraitY = rowTop - PC_CARD.w; // the square picture above the name cards
    const topY = rowTop - 170; // the top row of the player area: labels
    const badge = label(p, bx, topY, 'player-badge');
    TABLE.players[i].badgeEl = badge;
    badge.style.setProperty('--player', PLAYER_COLORS[i % PLAYER_COLORS.length]);
    const portraitSlot = addZone({
      accepts: 'relationship', faceDown: true, x: portraitX, y: portraitY, w: PC_CARD.w, h: PC_CARD.h,
      el: zoneOutline(portraitX, portraitY, PC_CARD.w, PC_CARD.w, 'Portrait', 0, 'tucked-zone'),
    });
    if (!fresh) {
      const portrait = placePcCard(drawEven(relationships), portraitX, portraitY, false);
      snapTo(portrait, portraitSlot, false);
      portrait.el.classList.add('tucked-name'); // under the name cards and the board
    }

    // Concept + first name, Trouble + last name, Asset + its condition: in each slot a spare
    // card is flipped and tucked underneath so one of its names reads above the card.
    const conceptSlot = cardSlot('concept', conceptX(sheetX), rowTop + PEEK);
    const troubleSlot = cardSlot('trouble', troubleX(sheetX), rowTop + PEEK);
    // The Storyteller token's spot: above Liability 1.
    TABLE.players[i].obstacleHome = { x: boardR + PC_CARD.w / 2, y: rowTop - 30 };
    const boonSlot = cardSlot('boon', bx, boonTop);
    if (!fresh) boonSlot.el.classList.add('hidden-zone'); // the board's strip marks it (shown while building a character)
    let dice;
    if (fresh) {
      dice = buildSheet(sheetX, sheetY, null, null);
    } else {
      const concept = dealIntoSlot(conceptSlot, concepts);
      const trouble = dealIntoSlot(troubleSlot, troubles);
      snapTo(placePcCard(drawEven(boons), boonSlot.x, boonSlot.y), boonSlot, false); // no name card: an Asset is just what it is
      dice = buildSheet(sheetX, sheetY, concept.card, trouble.card);
    }

    // Spotlight tokens: one stack above the portrait, beside the player's badge. Scored ones
    // go in a row under the sheet.
    const supplyX = bx + 8;
    const supplyY = rowTop - SPOTLIGHT_SIZE - 10; // the bottom token, above Asset 1
    // With takeSpotlight there's no personal supply: the spot holds the tokens taken this scene.
    const supply = SIM_RULES.takeSpotlight ? [] : placeSpotlightTokens(p, PLAYER_COLORS[i % PLAYER_COLORS.length], supplyX, supplyY);
    // (With scoreAtOnce there's no This scene stack: spotlight scores the moment it's taken.)
    if (!SIM_RULES.scoreAtOnce) countedLabel(SIM_RULES.takeSpotlight ? 'This scene' : 'Spotlight', bx + 46, topY + 2, 'pair-label stack-label big-count', 'spotlight',
      { x: supplyX - 20, y: supplyY - SPOTLIGHT_TOKENS * SPOTLIGHT_STEP - 20, w: SPOTLIGHT_SIZE + 40, h: SPOTLIGHT_TOKENS * SPOTLIGHT_STEP + SPOTLIGHT_SIZE + 26 });

    // The player's approach die (six approaches): overlapping the portrait's top right corner,
    // until they go in as a Main and set it in their box on the Board.
    const approachDieHome = { x: portraitX + PC_CARD.w - DIE_SIZE + 12, y: portraitY - 12 };
    const approachDie = createDie({ className: 'die-approach', size: DIE_SIZE, faces: APPROACHES, value: randInt(6) + 1, x: approachDieHome.x, y: approachDieHome.y });

    // Liability: a bad thing that has happened to the character. Just off the board's right edge,
    // level with the Asset, so both cards that can be compelled (Trouble, Liability) are on the right.
    const baneSlot = addZone({
      accepts: 'bane', x: boardR, y: boonTop, w: PC_CARD.w, h: PC_CARD.h,
      el: zoneOutline(boardR, boonTop, PC_CARD.w, PC_CARD.h, '', 0, 'hidden-zone'), // the board's strip marks it
    });
    // Story Points left of the portrait, Scored spotlight right of it.
    // Each label has its tokens just below it: stacks of STORY_STACK / SCORE_STACK tokens, two side by
    // side (a stack rises a few px per token, so there's room above the first).
    const scoreLabelY = topY;
    // With no This scene stack (scoreAtOnce), Spotlight, the one that matters most, goes top left beside
    // the badge, and Story Points right of the portrait, clear of the approach die on its corner.
    const rightOfPortrait = portraitX + PC_CARD.w + 34;
    const scoreX = SIM_RULES.scoreAtOnce ? bx + 46 : portraitX + PC_CARD.w + 10;
    const scoreY = scoreLabelY + 58 + (SCORE_STACK - 1) * 4; // under its two-line label
    const edgeLabelY = scoreLabelY;
    const edgeY = edgeLabelY + 58 + (STORY_STACK - 1) * 3;
    const edgeX = SIM_RULES.scoreAtOnce ? rightOfPortrait : boardX + 26; // (or clear of the This scene label to its left)
    countedLabel('Story Points', edgeX, edgeLabelY, 'pair-label stack-label big-count', 'edge', { x: edgeX - 10, w: PC_CARD.w + 8, y: edgeLabelY - 4, h: edgeY + EDGE_SIZE - edgeLabelY + 8 });
    countedLabel(SIM_RULES.scoreAtOnce ? 'Spotlight' : 'Scored spotlight', scoreX, scoreLabelY, 'pair-label stack-label big-count', 'spotlight', { x: scoreX - 10, w: PC_CARD.w + 8, y: scoreLabelY - 4, h: scoreY + SPOTLIGHT_SIZE - scoreLabelY + 8 });
    // Two player reference cards under the area, one showing each side.
    const refY = Math.max(boonTop + STACK_STEP + PC_CARD.h, sheetY + SHEET_H + 10) + 24;
    const refX = bx + (AREA_W - 2 * EL_CARD.w - EL_GAP) / 2;
    [true, false].forEach((up, k) => createCard({
      className: 'ref-card', w: EL_CARD.w, h: EL_CARD.h, x: refX + k * (EL_CARD.w + EL_GAP), y: refY, faceUp: up,
      front: refRoundSide(), back: refRollSide(),
    }));
    charBottom = Math.max(charBottom, refY + EL_CARD.h);
    Object.assign(TABLE.players[i], {
      zones: { concept: conceptSlot, trouble: troubleSlot, boon: boonSlot, bane: baneSlot, portrait: portraitSlot },
      dice, supply, scored: [], edge: [], scene: [], approachDie, approachDieHome,
      sceneAt: { x: supplyX, y: supplyY },
      scoreAt: { x: scoreX, y: scoreY },
      edgeAt: { x: edgeX, y: edgeY },
      // Where tokens land, at random, in an overlapping pile under each label (top-left corners; kept
      // inside the area the label counts).
      scorePile: { x: scoreX - 4, y: scoreLabelY + 54, w: PC_CARD.w - SPOTLIGHT_SIZE, h: scoreY - scoreLabelY - 54 },
      edgePile: { x: edgeX - 4, y: edgeLabelY + 54, w: PC_CARD.w - EDGE_SIZE - 34, h: edgeY - edgeLabelY - 50 }, // (narrower: the Storyteller token sits to its right)
    });
  });

  // The Storyteller token starts by the first player's Trouble (they're the first Storyteller),
  // with the Obstacle die in its slot.
  TABLE.obstacleDie = TABLE.storyToken = null;
  if (hasStoryteller()) {
    const home = TABLE.players[0].obstacleHome;
    TABLE.storyToken = createToken({ className: 'storyteller', size: STORY_SIZE, html: STORY_FACE, x: home.x - STORY_SIZE / 2, y: home.y - STORY_SIZE / 2 });
    if (SIM_RULES.obstacle) TABLE.obstacleDie = createDie({ className: 'die-obstacle', size: OBSTACLE_SIZE, faces: APPROACHES, value: 1, x: home.x - OBSTACLE_SIZE / 2, y: home.y - OBSTACLE_SIZE / 2 - OBSTACLE_RIDE });
  }

  // The shared spotlight pool, under the Fate deck, and the first stacks on the Board.
  if (SIM_RULES.takeSpotlight) {
    const n = SPOTLIGHT_TOKENS * players.length;
    // Under the Fate deck, centred in its column, with its label just above the Object's name card.
    const cols = Math.ceil(n / POOL_COLUMN);
    TABLE.poolAt = { x: OBJ_X + (EL_CARD.w - cols * (SPOTLIGHT_SIZE + 10) + 10) / 2, y: OBJECT_Y - PEEK - 6 - 20 - 6 - SPOTLIGHT_SIZE };
    TABLE.pool = [];
    for (let k = 0; k < n; k++) {
      const s = poolSpot(k);
      const t = createToken({ className: 'spotlight', size: SPOTLIGHT_SIZE, html: spotlightArt(''), x: s.x, y: s.y });
      t.el.style.setProperty('--tok', POOL_COLOR);
      t.player = null;
      TABLE.pool.push(t);
    }
    countedLabel('Spotlight pool', TABLE.poolAt.x, TABLE.poolAt.y + SPOTLIGHT_SIZE + 6, 'pair-label', 'spotlight',
      { x: TABLE.poolAt.x - 10, y: TABLE.poolAt.y - POOL_COLUMN * SPOTLIGHT_STEP - 10, w: cols * (SPOTLIGHT_SIZE + 10) + 20, h: POOL_COLUMN * SPOTLIGHT_STEP + SPOTLIGHT_SIZE + 20 });
    fillSuccessStacks(actTarget(SIM_RULES.acts[0], players.length));
  }

  worldSize.w = Math.max(TOP_R, CHARS_R) + 40;
  worldSize.h = Math.max(charBottom + 40, topBottom + 40);

  // ---- New game: the pool of character cards to choose from ----
  if (fresh) {
    TABLE.heightWithoutPool = worldSize.h;
    const POOL_TOP = worldSize.h + 50;
    const STEP = PC_CARD.w + 16;
    // Two of each character card per player (one to play, one spare for its name), and the
    // Relationships, all face up: the ring's first, then the rest flipped over as portraits.
    // `null` leaves a gap between groups.
    const n = players.length;
    const up = card => ({ card, faceUp: true });
    const rels = relationships.splice(-(relationshipCount(n) + n)).map(up);
    const half = Math.ceil(rels.length / 2);
    const rows = [
      [...concepts.slice(-2 * n).map(up), null, ...rels.slice(0, half)],
      [...troubles.slice(-2 * n).map(up), null, ...rels.slice(half)],
      boons.slice(-2 * n).map(up),
    ];
    TABLE.pool = [];
    rows.forEach((row, r) => row.forEach((item, c) => {
      if (item) TABLE.pool.push(placePcCard(item.card, 40 + c * STEP, POOL_TOP + r * (PC_CARD.h + 24), item.faceUp));
    }));
    worldSize.h = POOL_TOP + rows.length * (PC_CARD.h + 24) + 30;
  }

  updateSceneBoard(); // now the character badges exist, mark the ones the Scene die favours
  updateBuild();

  // Little "dealt" animation, staggered across the table.
  pieces.forEach((p, i) => {
    p.el.style.setProperty('--deal-delay', `${Math.min(i * 8, 500)}ms`);
    animateOnce(p, 'dealing', 1000);
  });
}

document.getElementById('reset-btn').addEventListener('click', () => {
  deal('deal');
  fitView();
});

document.getElementById('new-game-btn').addEventListener('click', () => {
  deal('new');
  fitView();
});

// ---- Player count picker: changing it deals a fresh table for that many players ----

const MIN_PLAYERS = 2, MAX_PLAYERS = 4;
let PLAYER_COUNT = 4;
let HUMAN_SEAT = false; // true: you play W in the simulator, the bots play the rest
const playersSelect = document.getElementById('players-select');

// `n`: a count ("3": all bots) or a count with "h" ("3h": you + bots).
function setPlayerCount(n) {
  HUMAN_SEAT = String(n).endsWith('h');
  PLAYER_COUNT = Math.max(MIN_PLAYERS, Math.min(MAX_PLAYERS, parseInt(n, 10) || 4));
  playersSelect.value = `${PLAYER_COUNT}${HUMAN_SEAT ? 'h' : ''}`;
  try { localStorage.setItem('card-rpg-players', playersSelect.value); } catch { /* storage unavailable */ }
}

playersSelect.innerHTML = Array.from({ length: MAX_PLAYERS - MIN_PLAYERS + 1 }, (_, i) => MIN_PLAYERS + i)
  .map(n => `<option value="${n}">${n} players (${n} bots)</option><option value="${n}h">${n} players (${n - 1} bot${n > 2 ? 's' : ''})</option>`).join('');
playersSelect.addEventListener('change', () => {
  setPlayerCount(playersSelect.value);
  deal('deal');
  fitView();
});

let savedPlayers = '4';
try { savedPlayers = localStorage.getItem('card-rpg-players') || '4'; } catch { /* storage unavailable */ }
setPlayerCount(savedPlayers);

// ---- Card set picker: tick one or more sets; changing them re-deals with their cards mixed ----

const setPicker = document.getElementById('set-picker');
const setButton = document.getElementById('set-btn');
const setMenu = document.getElementById('set-menu');

function setSets(keys) {
  SETS = Object.keys(THEMES).filter(k => keys.includes(k));
  if (!SETS.length) SETS = DEFAULT_SETS;
  DATA = mergeSets(SETS);
  setMenu.querySelectorAll('input').forEach(box => { box.checked = SETS.includes(box.value); box.disabled = box.checked && SETS.length === 1; }); // keep at least one
  setButton.textContent = SETS.map(k => THEMES[k].label).join(' + ');
  document.body.dataset.theme = SETS.length === 1 ? SETS[0] : 'mix'; // a set's own table colour only when it's alone
  try { localStorage.setItem('card-rpg-sets', JSON.stringify(SETS)); } catch { /* storage unavailable */ }
}

setMenu.innerHTML = Object.entries(THEMES).map(([key, t]) => `<label class="set-option"><input type="checkbox" value="${key}"><span>${esc(t.label)}</span></label>`).join('');
setButton.addEventListener('click', () => { setMenu.hidden = !setMenu.hidden; });
document.addEventListener('pointerdown', e => { if (!setPicker.contains(e.target)) setMenu.hidden = true; });
setMenu.addEventListener('change', () => {
  setSets([...setMenu.querySelectorAll('input:checked')].map(box => box.value));
  deal('deal');
  fitView();
});

// The game is always three acts (Beginning, Middle, Ending) at the tuned stack sizes; the
// game-length pickers were removed 2026-10-19 (setGameLength in rules.js still allows others).
setGameLength(1, 1);
try { localStorage.removeItem('card-rpg-length'); } catch { /* storage unavailable */ }

let savedSets = DEFAULT_SETS; // Blade Runner alone unless other sets were picked before
try { savedSets = JSON.parse(localStorage.getItem('card-rpg-sets')) || savedSets; } catch { /* storage unavailable */ }
setSets(Array.isArray(savedSets) ? savedSets : DEFAULT_SETS); // unknown sets (e.g. the old Film Noir) drop out

deal();
fitView();
window.addEventListener('resize', fitView);
